import zlib
from datetime import datetime, timezone

import numpy as np
import pandas as pd

from app.providers.base import MarketDataProvider
from app.providers.universe import find_instruments
from app.schemas.market import DataLabel, Quote, SymbolInfo
from app.utils.errors import InvalidRequestError

IST = "Asia/Kolkata"
COLUMNS = ["open", "high", "low", "close", "adj_close", "volume"]
DEMO_NOTE = (
    "DEMO DATA: synthetic prices generated by code. This is NOT real market data. "
    "Models trained on it are meaningless for real investing."
)


class DemoProvider(MarketDataProvider):
    """Deterministic fake daily data. Same symbol -> same series."""

    name = "demo"

    def search(self, query: str) -> list[SymbolInfo]:
        return [
            SymbolInfo(symbol=s, exchange=ex, name=n, provider_symbol=f"DEMO:{ex}:{s}")
            for s, n in find_instruments(query)
            for ex in ("NSE", "BSE")
        ]

    def get_history(
        self, symbol: str, lookback_days: int, interval: str = "1d", exchange: str = "NSE"
    ) -> pd.DataFrame:
        if interval != "1d":
            raise InvalidRequestError("The demo provider supports only the '1d' interval.")
        rng = np.random.default_rng(zlib.crc32(f"{exchange}:{symbol}".encode()))
        end = pd.Timestamp(datetime.now(timezone.utc).astimezone().date())
        dates = pd.bdate_range(end=end, periods=max(2, int(lookback_days * 5 / 7)), tz=IST)
        n = len(dates)

        returns = rng.normal(0.0004, 0.015, n)
        start_price = 500 + (zlib.crc32(symbol.encode()) % 2500)
        close = start_price * np.exp(np.cumsum(returns))
        open_ = np.roll(close, 1) * (1 + rng.normal(0, 0.003, n))
        open_[0] = start_price
        high = np.maximum(open_, close) * (1 + np.abs(rng.normal(0, 0.006, n)))
        low = np.minimum(open_, close) * (1 - np.abs(rng.normal(0, 0.006, n)))
        volume = (rng.integers(1_000_000, 5_000_000, n) * (1 + np.abs(returns) * 20)).astype(int)

        df = pd.DataFrame(
            {
                "open": open_.round(2), "high": high.round(2), "low": low.round(2),
                "close": close.round(2), "adj_close": close.round(2), "volume": volume,
            },
            index=dates,
        )[COLUMNS]
        df.index.name = "timestamp"
        return df

    def get_quote(self, symbol: str, exchange: str = "NSE") -> Quote:
        df = self.get_history(symbol, 30, "1d", exchange)
        last, prev = df.iloc[-1], df.iloc[-2]
        return Quote(
            symbol=symbol, exchange=exchange, price=float(last["close"]),
            previous_close=float(prev["close"]),
            change_pct=round((last["close"] - prev["close"]) / prev["close"] * 100, 2),
            day_high=float(last["high"]), day_low=float(last["low"]), volume=int(last["volume"]),
            as_of=df.index[-1].to_pydatetime(), fetched_at=datetime.now(timezone.utc),
            label=DataLabel.DEMO, provider=self.name, note=DEMO_NOTE,
        )